INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES
('o10-A1-1', 'q0100001-0000-0000-0000-000000000001', 'Memperbanyak jumlah halaman website', 0, 'Keliru. Menambah halaman tanpa evaluasi justru berpotensi memperlambat performa dan membingungkan navigasi.'),
('o10-A1-2', 'q0100001-0000-0000-0000-000000000001', 'Menilai dan meningkatkan kualitas website dari berbagai aspek', 10, 'Tepat! Audit kualitas web mengevaluasi performa, aksesibilitas, SEO, dan praktik terbaik guna menyempurnakan pengalaman pengguna.'),
('o10-A1-3', 'q0100001-0000-0000-0000-000000000001', 'Mengganti framework website', 0, 'Keliru. Audit bertujuan mengevaluasi kualitas aplikasi saat ini, bukan serta-merta mengganti framework.'),
('o10-A1-4', 'q0100001-0000-0000-0000-000000000001', 'Menambah jumlah gambar', 0, 'Keliru. Gambar berlebihan tanpa optimasi justru menurunkan skor kecepatan halaman.'),
('o10-A2-1', 'q0100001-0000-0000-0000-000000000002', 'Figma', 0, 'Keliru. Figma adalah tools untuk perancangan UI/UX dan prototyping.'),
('o10-A2-2', 'q0100001-0000-0000-0000-000000000002', 'GitHub', 0, 'Keliru. GitHub adalah platform kolaborasi repository kode.'),
('o10-A2-3', 'q0100001-0000-0000-0000-000000000002', 'Lighthouse', 10, 'Tepat! Google Lighthouse digunakan untuk mengaudit Performance, Accessibility, Best Practices, dan SEO.'),
('o10-A2-4', 'q0100001-0000-0000-0000-000000000002', 'Canva', 0, 'Keliru. Canva adalah alat desain grafis, bukan tool audit teknis web.'),
('o10-A3-1', 'q0100001-0000-0000-0000-000000000003', 'Microsoft', 0, 'Keliru. Microsoft mengembangkan Microsoft Clarity dan Playwright.'),
('o10-A3-2', 'q0100001-0000-0000-0000-000000000003', 'Google', 10, 'Tepat! Lighthouse merupakan alat audit open-source besutan Google yang terintegrasi di Chrome DevTools.'),
('o10-A3-3', 'q0100001-0000-0000-0000-000000000003', 'Meta', 0, 'Keliru. Meta mengembangkan React.'),
('o10-A3-4', 'q0100001-0000-0000-0000-000000000003', 'Mozilla', 0, 'Keliru. Mozilla mengembangkan Firefox dan MDN Web Docs.'),
('o10-A4-1', 'q0100001-0000-0000-0000-000000000004', 'Performance', 0, 'Kurang lengkap. Performance memang kategori Lighthouse, namun Accessibility dan SEO juga termasuk.'),
('o10-A4-2', 'q0100001-0000-0000-0000-000000000004', 'Accessibility', 0, 'Kurang lengkap. Accessibility termasuk, bersama Performance, Best Practices, dan SEO.'),
('o10-A4-3', 'q0100001-0000-0000-0000-000000000004', 'SEO', 0, 'Kurang lengkap. SEO termasuk salah satu dari empat pilar audit utama Lighthouse.'),
('o10-A4-4', 'q0100001-0000-0000-0000-000000000004', 'Semua benar', 10, 'Tepat! Empat kategori penilaian Lighthouse adalah Performance, Accessibility, Best Practices, dan SEO.'),
('o10-A5-1', 'q0100001-0000-0000-0000-000000000005', 'Kualitas desain visual', 0, 'Keliru. Estetika visual dievaluasi melalui design review dan usability testing.'),
('o10-A5-2', 'q0100001-0000-0000-0000-000000000005', 'Kecepatan dan efisiensi website', 10, 'Tepat! Kategori Performance menilai seberapa cepat halaman dimuat, dirender, dan merespons interaksi pengguna.'),
('o10-A5-3', 'q0100001-0000-0000-0000-000000000005', 'Jumlah pengguna website', 0, 'Keliru. Jumlah pengguna dipantau melalui tools analitik trafik.'),
('o10-A5-4', 'q0100001-0000-0000-0000-000000000005', 'Banyaknya halaman website', 0, 'Keliru.'),
('o10-A6-1', 'q0100001-0000-0000-0000-000000000006', 'Kemudahan website diakses semua pengguna termasuk penyandang disabilitas', 10, 'Tepat! Accessibility memastikan aplikasi inklusif bagi pengguna screen reader, navigasi keyboard, maupun keterbatasan penglihatan.'),
('o10-A6-2', 'q0100001-0000-0000-0000-000000000006', 'Kecepatan database', 0, 'Keliru. Kecepatan query masuk ranah optimasi backend/database.'),
('o10-A6-3', 'q0100001-0000-0000-0000-000000000006', 'Tampilan animasi', 0, 'Keliru.'),
('o10-A6-4', 'q0100001-0000-0000-0000-000000000006', 'Struktur folder proyek', 0, 'Keliru.'),
('o10-A7-1', 'q0100001-0000-0000-0000-000000000007', 'Memastikan website mengikuti standar pengembangan yang baik', 10, 'Tepat! Best Practices memeriksa aspek keamanan browser, penggunaan HTTPS, bebas error console, dan API modern.'),
('o10-A7-2', 'q0100001-0000-0000-0000-000000000007', 'Menambah fitur website', 0, 'Keliru.'),
('o10-A7-3', 'q0100001-0000-0000-0000-000000000007', 'Mengurangi ukuran monitor', 0, 'Keliru.'),
('o10-A7-4', 'q0100001-0000-0000-0000-000000000007', 'Mengubah domain', 0, 'Keliru.'),
('o10-A8-1', 'q0100001-0000-0000-0000-000000000008', 'Memperindah tampilan website', 0, 'Keliru. Tampilan diatur melalui CSS dan sistem desain.'),
('o10-A8-2', 'q0100001-0000-0000-0000-000000000008', 'Membantu website lebih mudah ditemukan mesin pencari', 10, 'Tepat! Audit SEO memastikan halaman dapat diindeks dan dipahami dengan baik oleh crawler mesin pencari.'),
('o10-A8-3', 'q0100001-0000-0000-0000-000000000008', 'Mengurangi ukuran gambar', 0, 'Keliru. Kompresi gambar termasuk optimasi Performance.'),
('o10-A8-4', 'q0100001-0000-0000-0000-000000000008', 'Menambah plugin', 0, 'Keliru.'),
('o10-A9-1', 'q0100001-0000-0000-0000-000000000009', 'Largest Component Paint', 0, 'Keliru. Kata keduanya adalah Contentful, bukan Component.'),
('o10-A9-2', 'q0100001-0000-0000-0000-000000000009', 'Largest Contentful Paint', 10, 'Tepat! Largest Contentful Paint (LCP) mengukur waktu render elemen konten terbesar di viewport.'),
('o10-A9-3', 'q0100001-0000-0000-0000-000000000009', 'Long Content Process', 0, 'Keliru.'),
('o10-A9-4', 'q0100001-0000-0000-0000-000000000009', 'Layout Content Paint', 0, 'Keliru.'),
('o10-A10-1', 'q0100001-0000-0000-0000-000000000010', '≤ 2,5 detik', 10, 'Tepat! Standar Core Web Vitals menetapkan skor LCP yang baik berada di angka 2,5 detik atau lebih cepat.'),
('o10-A10-2', 'q0100001-0000-0000-0000-000000000010', '≤ 5 detik', 0, 'Keliru. Angka di atas 4 detik sudah masuk kategori Poor (buruk).'),
('o10-A10-3', 'q0100001-0000-0000-0000-000000000010', '≤ 10 detik', 0, 'Keliru. 10 detik sangat lambat dan memicu bounce rate tinggi.'),
('o10-A10-4', 'q0100001-0000-0000-0000-000000000010', '≤ 15 detik', 0, 'Keliru.'),
('o10-B1-1', 'q0100003-0000-0000-0000-000000000001', 'Internal Navigation Page', 0, 'Keliru.'),
('o10-B1-2', 'q0100003-0000-0000-0000-000000000001', 'Interaction to Next Paint', 10, 'Tepat! Interaction to Next Paint (INP) menggantikan FID sebagai metrik responsivitas interaksi Core Web Vitals.'),
('o10-B1-3', 'q0100003-0000-0000-0000-000000000001', 'Interactive New Process', 0, 'Keliru.'),
('o10-B1-4', 'q0100003-0000-0000-0000-000000000001', 'Internet Navigation Point', 0, 'Keliru.'),
('o10-B2-1', 'q0100003-0000-0000-0000-000000000002', '≤ 200 ms', 10, 'Tepat! Latensi interaksi ≤ 200 milidetik membuat antarmuka terasa instan dan responsif bagi pengguna.'),
('o10-B2-2', 'q0100003-0000-0000-0000-000000000002', '≤ 2 detik', 0, 'Keliru. 2 detik (2000 ms) jauh melampaui ambang batas responsivitas yang baik.'),
('o10-B2-3', 'q0100003-0000-0000-0000-000000000002', '≤ 1 detik', 0, 'Keliru. 1 detik (1000 ms) sudah termasuk kategori Poor (> 500 ms).'),
('o10-B2-4', 'q0100003-0000-0000-0000-000000000002', '≤ 500 ms', 0, 'Keliru. Rentang 200–500 ms masih tergolong Needs Improvement.'),
('o10-B3-1', 'q0100003-0000-0000-0000-000000000003', 'Cumulative Layout Shift', 10, 'Tepat! Cumulative Layout Shift (CLS) mengukur total pergeseran tata letak tak terduga selama siklus hidup halaman.'),
('o10-B3-2', 'q0100003-0000-0000-0000-000000000003', 'Content Layout Structure', 0, 'Keliru.'),
('o10-B3-3', 'q0100003-0000-0000-0000-000000000003', 'Component Loading Speed', 0, 'Keliru.'),
('o10-B3-4', 'q0100003-0000-0000-0000-000000000003', 'Client Layout Scale', 0, 'Keliru.'),
('o10-B4-1', 'q0100003-0000-0000-0000-000000000004', 'Stabilitas tata letak halaman', 10, 'Tepat! CLS mendeteksi elemen yang melompat tiba-tiba saat gambar atau font selesai dimuat sehingga mencegah salah klik.'),
('o10-B4-2', 'q0100003-0000-0000-0000-000000000004', 'Kecepatan server', 0, 'Keliru. Kecepatan respons awal server diukur oleh Time to First Byte (TTFB).'),
('o10-B4-3', 'q0100003-0000-0000-0000-000000000004', 'Jumlah konten website', 0, 'Keliru.'),
('o10-B4-4', 'q0100003-0000-0000-0000-000000000004', 'Ukuran file JavaScript', 0, 'Keliru.'),
('o10-B5-1', 'q0100003-0000-0000-0000-000000000005', '≤ 1.0', 0, 'Keliru. Nilai 1.0 menunjukkan pergeseran layout yang sangat parah.'),
('o10-B5-2', 'q0100003-0000-0000-0000-000000000005', '≤ 0.5', 0, 'Keliru. Skor > 0.25 sudah tergolong Poor.'),
('o10-B5-3', 'q0100003-0000-0000-0000-000000000005', '≤ 0.1', 10, 'Tepat! Nilai CLS ≤ 0.1 menjamin tata letak halaman tetap stabil selama proses pemuatan.'),
('o10-B5-4', 'q0100003-0000-0000-0000-000000000005', '≤ 2.0', 0, 'Keliru.'),
('o10-B6-1', 'q0100003-0000-0000-0000-000000000006', 'SEO dan aksesibilitas', 10, 'Tepat! Atribut alt dibaca oleh screen reader bagi pengguna tunanetra sekaligus membantu mesin pencari memahami konteks gambar.'),
('o10-B6-2', 'q0100003-0000-0000-0000-000000000006', 'Menambah ukuran gambar', 0, 'Keliru. Alt text hanya berupa teks deskriptif ringan.'),
('o10-B6-3', 'q0100003-0000-0000-0000-000000000006', 'Menambah warna gambar', 0, 'Keliru.'),
('o10-B6-4', 'q0100003-0000-0000-0000-000000000006', 'Mempercepat hosting', 0, 'Keliru.'),
('o10-B7-1', 'q0100003-0000-0000-0000-000000000007', 'Website terlihat lebih mahal', 0, 'Keliru.'),
('o10-B7-2', 'q0100003-0000-0000-0000-000000000007', 'Teks mudah dibaca oleh pengguna', 10, 'Tepat! Rasio kontras minimal 4,5:1 (WCAG AA) memastikan teks terbaca jelas di berbagai kondisi layar dan penglihatan.'),
('o10-B7-3', 'q0100003-0000-0000-0000-000000000007', 'File CSS lebih kecil', 0, 'Keliru.'),
('o10-B7-4', 'q0100003-0000-0000-0000-000000000007', 'Gambar menjadi HD', 0, 'Keliru.'),
('o10-B8-1', 'q0100003-0000-0000-0000-000000000008', 'Memberikan konteks dan aksesibilitas pada input formulir', 10, 'Tepat! Tag <label> yang terhubung dengan <input> memperluas area klik dan membantu screen reader membacakan fungsi kolom.'),
('o10-B8-2', 'q0100003-0000-0000-0000-000000000008', 'Menambah data database', 0, 'Keliru.'),
('o10-B8-3', 'q0100003-0000-0000-0000-000000000008', 'Menghubungkan API', 0, 'Keliru.'),
('o10-B8-4', 'q0100003-0000-0000-0000-000000000008', 'Membuat animasi', 0, 'Keliru.'),
('o10-B9-1', 'q0100003-0000-0000-0000-000000000009', 'Menampilkan judul halaman pada browser dan mesin pencari', 10, 'Tepat! Tag <title> muncul di tab browser serta menjadi judul utama tautan pada halaman hasil pencarian (SERP).'),
('o10-B9-2', 'q0100003-0000-0000-0000-000000000009', 'Menyimpan data pengguna', 0, 'Keliru.'),
('o10-B9-3', 'q0100003-0000-0000-0000-000000000009', 'Menjalankan JavaScript', 0, 'Keliru.'),
('o10-B9-4', 'q0100003-0000-0000-0000-000000000009', 'Mengubah warna website', 0, 'Keliru.'),
('o10-B10-1', 'q0100003-0000-0000-0000-000000000010', 'Menyimpan password pengguna', 0, 'Keliru. Password tidak pernah disimpan di tag HTML.'),
('o10-B10-2', 'q0100003-0000-0000-0000-000000000010', 'Memberikan ringkasan isi halaman kepada mesin pencari', 10, 'Tepat! Meta description menyediakan cuplikan ringkas halaman di bawah judul pada hasil pencarian untuk meningkatkan rasio klik.'),
('o10-B10-3', 'q0100003-0000-0000-0000-000000000010', 'Membuat database', 0, 'Keliru.'),
('o10-B10-4', 'q0100003-0000-0000-0000-000000000010', 'Mengubah layout', 0, 'Keliru.'),
('o10-C1-1', 'q0100005-0000-0000-0000-000000000001', 'h6', 0, 'Keliru. h6 adalah tingkatan heading paling kecil.'),
('o10-C1-2', 'q0100005-0000-0000-0000-000000000001', 'h5', 0, 'Keliru.'),
('o10-C1-3', 'q0100005-0000-0000-0000-000000000001', 'h3', 0, 'Keliru.'),
('o10-C1-4', 'q0100005-0000-0000-0000-000000000001', 'h1', 10, 'Tepat! Hierarki heading semantik dimulai dari satu <h1> utama lalu turun berurutan ke <h2>, <h3>, dan seterusnya.'),
('o10-C2-1', 'q0100005-0000-0000-0000-000000000002', 'Mengatur tampilan website saat dibagikan ke media sosial', 10, 'Tepat! Tag Open Graph (og:title, og:description, og:image) mengontrol kartu pratinjau tautan saat dibagikan di media sosial.'),
('o10-C2-2', 'q0100005-0000-0000-0000-000000000002', 'Mengoptimalkan database', 0, 'Keliru.'),
