('o10-C3-1', 'q0100005-0000-0000-0000-000000000003', 'Mengenkripsi komunikasi antara pengguna dan server', 10, 'Tepat! HTTPS menggunakan enkripsi TLS untuk mencegah penyadapan (MITM) dan menjaga integritas data selama transmisi.'),
('o10-C3-2', 'q0100005-0000-0000-0000-000000000003', 'Membuat website lebih berwarna', 0, 'Keliru.'),
('o10-C3-3', 'q0100005-0000-0000-0000-000000000003', 'Mengurangi jumlah halaman', 0, 'Keliru.'),
('o10-C3-4', 'q0100005-0000-0000-0000-000000000003', 'Menambah ukuran file', 0, 'Keliru.'),
('o10-C4-1', 'q0100005-0000-0000-0000-000000000004', 'Menyimpan konfigurasi sensitif seperti API Key', 10, 'Tepat! File .env memisahkan rahasia konfigurasi dari repositori Git publik agar tidak bocor.'),
('o10-C4-2', 'q0100005-0000-0000-0000-000000000004', 'Menyimpan gambar website', 0, 'Keliru. Aset gambar disimpan di folder public/ atau assets/.'),
('o10-C4-3', 'q0100005-0000-0000-0000-000000000004', 'Menyimpan CSS', 0, 'Keliru.'),
('o10-C4-4', 'q0100005-0000-0000-0000-000000000004', 'Menyimpan wireframe', 0, 'Keliru.'),
('o10-C5-1', 'q0100005-0000-0000-0000-000000000005', 'Membersihkan input dari potensi data berbahaya', 10, 'Tepat! Sanitasi menyaring karakter atau tag skrip berbahaya sebelum data diproses atau dirender ke DOM.'),
('o10-C5-2', 'q0100005-0000-0000-0000-000000000005', 'Menambah jumlah data', 0, 'Keliru.'),
('o10-C5-3', 'q0100005-0000-0000-0000-000000000005', 'Mempercepat monitor', 0, 'Keliru.'),
('o10-C5-4', 'q0100005-0000-0000-0000-000000000005', 'Menambah warna halaman', 0, 'Keliru.'),
('o10-C6-1', 'q0100005-0000-0000-0000-000000000006', 'Extended Server Storage', 0, 'Keliru.'),
('o10-C6-2', 'q0100005-0000-0000-0000-000000000006', 'Cross-Site Scripting', 10, 'Tepat! Cross-Site Scripting (XSS) adalah celah injeksi skrip berbahaya ke halaman web yang dilihat pengguna lain.'),
('o10-C6-3', 'q0100005-0000-0000-0000-000000000006', 'Cross System Security', 0, 'Keliru.'),
('o10-C6-4', 'q0100005-0000-0000-0000-000000000006', 'External Site Sharing', 0, 'Keliru.'),
('o10-C7-1', 'q0100005-0000-0000-0000-000000000007', 'Banyaknya warna yang digunakan', 0, 'Keliru. Penggunaan terlalu banyak warna justru melanggar konsistensi visual.'),
('o10-C7-2', 'q0100005-0000-0000-0000-000000000007', 'Proses pemecahan masalah dan dampak proyek', 10, 'Tepat! Rekruter menilai cara berpikir terstruktur, keputusan teknis/desain, serta hasil nyata yang terukur dari studi kasus.'),
('o10-C7-3', 'q0100005-0000-0000-0000-000000000007', 'Ukuran font website', 0, 'Keliru.'),
('o10-C7-4', 'q0100005-0000-0000-0000-000000000007', 'Jumlah animasi', 0, 'Keliru.'),
('o10-C8-1', 'q0100005-0000-0000-0000-000000000008', 'Discovery', 0, 'Keliru. Discovery adalah bagian kedua setelah Overview.'),
('o10-C8-2', 'q0100005-0000-0000-0000-000000000008', 'Engineering', 0, 'Keliru. Engineering adalah bagian ketiga.'),
('o10-C8-3', 'q0100005-0000-0000-0000-000000000008', 'Overview', 10, 'Tepat! Urutan struktur Case Study profesional adalah Overview → Discovery → Engineering → Testing → Impact.'),
('o10-C8-4', 'q0100005-0000-0000-0000-000000000008', 'Impact', 0, 'Keliru. Impact adalah bagian penutup (kelima).'),
('o10-C9-1', 'q0100005-0000-0000-0000-000000000009', 'Struktur database', 0, 'Keliru. Struktur database dijelaskan pada bagian Engineering.'),
('o10-C9-2', 'q0100005-0000-0000-0000-000000000009', 'Hasil dan dampak yang dicapai proyek', 10, 'Tepat! Bagian Impact menyajikan bukti pencapaian seperti skor Lighthouse, metrik SEQ, dan pembelajaran proyek.'),
('o10-C9-3', 'q0100005-0000-0000-0000-000000000009', 'Warna desain aplikasi', 0, 'Keliru.'),
('o10-C9-4', 'q0100005-0000-0000-0000-000000000009', 'Riwayat pendidikan', 0, 'Keliru. Riwayat pendidikan berada di halaman profil/CV, bukan di bagian Impact proyek.'),
('o10-C10-1', 'q0100005-0000-0000-0000-000000000010', 'Menampilkan proses, kemampuan, dan hasil kerja secara profesional', 10, 'Tepat! Showcase portofolio membuktikan kompetensi nyata kandidat dari perumusan masalah hingga produk teruji.'),
('o10-C10-2', 'q0100005-0000-0000-0000-000000000010', 'Menampilkan semua screenshot proyek tanpa penjelasan', 0, 'Keliru. Galeri tanpa narasi proses tidak menunjukkan kemampuan problem solving.'),
('o10-C10-3', 'q0100005-0000-0000-0000-000000000010', 'Menambah jumlah halaman website', 0, 'Keliru.'),
('o10-C10-4', 'q0100005-0000-0000-0000-000000000010', 'Menggantikan CV sepenuhnya', 0, 'Keliru. Portofolio melengkapi CV dengan bukti karya mendalam.');
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES
('er-0000010-0000-0000-0000-000000000001', 'q0100002-0000-0000-0000-000000000001', 'Audit kualitas web adalah proses evaluasi website berdasarkan aspek seperti performa, aksesibilitas, SEO, keamanan, dan best practices untuk meningkatkan kualitas pengalaman pengguna dan efektivitas website.', ARRAY['audit web', 'evaluasi website', 'performa', 'aksesibilitas', 'seo', 'kualitas']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Audit web adalah pengecekan website (terlalu umum dan tidak menjelaskan tujuan maupun aspek yang diuji)","8":"Audit kualitas web digunakan untuk meningkatkan website (belum menjelaskan aspek yang dievaluasi seperti performa, aksesibilitas, dan SEO)","9":"Audit kualitas web adalah proses memeriksa kualitas website dari berbagai aspek","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000002', 'q0100002-0000-0000-0000-000000000002', 'Lighthouse adalah alat audit otomatis yang digunakan untuk menilai performa, accessibility, best practices, dan SEO pada website.', ARRAY['lighthouse', 'audit', 'performance', 'accessibility', 'seo', 'best practices']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Lighthouse adalah tools web (terlalu umum)","8":"Lighthouse digunakan untuk mengecek website (belum menjelaskan kategori evaluasi yang diukur)","9":"Lighthouse digunakan untuk mengaudit kualitas website","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000003', 'q0100002-0000-0000-0000-000000000003', 'Performance mengukur kecepatan, efisiensi pemuatan halaman, serta responsivitas website ketika digunakan pengguna.', ARRAY['performa', 'kecepatan', 'loading', 'responsivitas']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000004', 'q0100002-0000-0000-0000-000000000004', 'Accessibility adalah upaya membuat website dapat digunakan oleh semua pengguna termasuk penyandang disabilitas sehingga pengalaman penggunaan menjadi inklusif.', ARRAY['accessibility', 'aksesibilitas', 'disabilitas', 'inklusif']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000005', 'q0100002-0000-0000-0000-000000000005', 'Best Practices memastikan website mengikuti standar pengembangan modern yang aman, stabil, dan dapat diandalkan.', ARRAY['best practices', 'standar', 'keamanan', 'kualitas kode']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000006', 'q0100004-0000-0000-0000-000000000001', 'SEO membantu website lebih mudah ditemukan di mesin pencari sehingga dapat meningkatkan jumlah pengunjung organik.', ARRAY['seo', 'mesin pencari', 'visibilitas', 'pengunjung']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000007', 'q0100004-0000-0000-0000-000000000002', 'LCP adalah metrik Core Web Vitals yang mengukur waktu yang dibutuhkan hingga elemen konten utama terbesar pada halaman berhasil ditampilkan.', ARRAY['lcp', 'core web vitals', 'konten utama', 'loading']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"LCP adalah metrik website (terlalu umum)","8":"LCP mengukur kecepatan loading (belum menjelaskan bahwa yang diukur adalah elemen konten terbesar pada halaman)","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000008', 'q0100004-0000-0000-0000-000000000003', 'INP (Interaction to Next Paint) mengukur respons aplikasi terhadap interaksi pengguna hingga perubahan visual berikutnya ditampilkan.', ARRAY['inp', 'interaksi', 'responsivitas', 'core web vitals']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000009', 'q0100004-0000-0000-0000-000000000004', 'CLS mengukur stabilitas tata letak halaman dengan mengamati pergeseran elemen visual yang tidak diharapkan selama proses loading.', ARRAY['cls', 'layout shift', 'stabilitas', 'loading']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000010', 'q0100004-0000-0000-0000-000000000005', 'Alt Text membantu aksesibilitas pengguna yang menggunakan screen reader dan memberikan informasi ketika gambar gagal dimuat.', ARRAY['alt text', 'screen reader', 'aksesibilitas', 'gambar']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000011', 'q0100006-0000-0000-0000-000000000001', 'HTTPS mengenkripsi komunikasi antara browser dan server sehingga data pengguna lebih aman saat ditransmisikan.', ARRAY['https', 'enkripsi', 'keamanan', 'komunikasi data']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000012', 'q0100006-0000-0000-0000-000000000002', 'File .env digunakan untuk menyimpan data sensitif seperti API key atau kredensial sehingga tidak ditulis langsung di source code.', ARRAY['.env', 'api key', 'kredensial', 'keamanan']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000013', 'q0100006-0000-0000-0000-000000000003', 'XSS (Cross-Site Scripting) adalah serangan yang memanfaatkan input tidak aman untuk menjalankan script berbahaya pada browser pengguna.', ARRAY['xss', 'cross-site scripting', 'script berbahaya', 'keamanan']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000014', 'q0100006-0000-0000-0000-000000000004', 'Karena menunjukkan proses berpikir, problem solving, keputusan teknis, proses pengujian, dan dampak nyata yang dihasilkan dari proyek.', ARRAY['case study', 'problem solving', 'proses', 'dampak', 'keputusan teknis']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Case study lebih baik daripada screenshot (terlalu umum)","8":"Case study membuat portofolio lebih menarik (belum menjelaskan aspek proses, keputusan, dan dampak yang dicari rekruter)","9":"Case study menunjukkan bagaimana proyek dikerjakan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000010-0000-0000-0000-000000000015', 'q0100006-0000-0000-0000-000000000005', '1. Overview – gambaran proyek. 2. Discovery – riset dan identifikasi masalah. 3. Engineering – proses implementasi teknis. 4. Testing – pengujian dan validasi. 5. Impact – hasil serta dampak proyek.', ARRAY['overview', 'discovery', 'engineering', 'testing', 'impact']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Case study berisi penjelasan proyek (tidak menjelaskan struktur yang dimaksud)","8":"Menyebutkan sebagian besar bagian tetapi tidak lengkap (belum mencakup seluruh struktur case study profesional)","9":"Menyebutkan kelima bagian dengan penjelasan singkat","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb);
